{
  "findings": [
    {
      "ref": "D501",
      "area": "age_gating",
      "claim": "The app is intended for children ages 2–8.",
      "stance": "neutral",
      "quote": "Packed with fun, standards-aligned reading games, math games, phonics lessons, and interactive storybooks, the app has helped over 21 million preschool and elementary students learn at home, at school, and on the go. Join Kodi the Bear and friends on exciting educational adventures that spark curiosity, build confidence, and inspire a lifelong love of learning."
    },
    {
      "ref": "D501",
      "area": "content",
      "claim": "The app includes characters Ollo the Elephant, Reya the Red Panda, Peck the Hummingbird, and Sandy the Dingo who lead activities in phonics, storytime, numbers, and puzzles.",
      "stance": "neutral",
      "quote": "From ABC games and phonics practice to counting, addition, and shapes, kids can explore over 5,000 educational games and activities with Kodi’s friends: • Ollo the Elephant – phonics and letter sounds • Reya the Red Panda – storytime and writing • Peck the Hummingbird – numbers and counting • Sandy the Dingo – puzzles, memory, and problem-solving."
    },
    {
      "ref": "D501",
      "area": "money",
      "claim": "The app is 100% free with no ads or subscriptions.",
      "stance": "mitigation",
      "quote": "Khan Academy Kids is 100% free—no ads, no subscriptions."
    },
    {
      "ref": "D501",
      "area": "data",
      "claim": "The app is COPPA-compliant, meaning it follows regulations for collecting data from children.",
      "stance": "mitigation",
      "quote": "Created in partnership with the Stanford Graduate School of Education by education experts, aligned with Head Start and Common Core Standards, COPPA-compliant, and 100% free—no ads, no subscriptions."
    },
    {
      "ref": "D502",
      "area": "contact",
      "claim": "A parent reports concern about screen time but does not mention any messaging or voice‑chat features.",
      "stance": "neutral",
      "quote": "Quiero probar \"Khan Academy Kids\" para nuestros pequeños, pero me preocupa el tiempo de pantalla."
    },
    {
      "ref": "D503",
      "area": "contact",
      "claim": "A parent reports that the app is used as a calm, limited screen activity and that the child sometimes pauses it to go outside or do puzzles.",
      "stance": "neutral",
      "quote": "My 4yo likes to play khan academy kids, but it's just a fun screen activity when we need the kids to be calm."
    },
    {
      "ref": "D504",
      "area": "money",
      "claim": "A reviewer notes that Khan Academy Kids includes in‑app rewards such as musical instruments, clothes for characters, and a bug house, and that there are no adverts.",
      "stance": "neutral",
      "quote": "It is free. It includes learning games that give rewards in the game like musical instruments, or clothes to play dress up on one of the characters, or (my son's favourite) bugs to add to a bug house. It also includes drawing/colouring in. There are no adverts either."
    },
    {
      "ref": "D505",
      "area": "data",
      "claim": "The app can be set up quickly for a child’s account, and the setup process is described as easy and free.",
      "stance": "neutral",
      "quote": "Khan Academy Kids is an award‑winning educational app for young learners ages two to seven. Watch this video to learn how to set up an account for your child and have them start learning. It’s quick and easy, and will take no more than a few minutes. Khan Academy Kids is available on iPhone, iPad, Google Play, and Amazon. It’s 100% free—no ads, no subscriptions."
    },
    {
      "ref": "D506",
      "area": "research",
      "claim": "A commenter cites research indicating that Khan Academy Kids boosts pre‑literacy skills.",
      "stance": "neutral",
      "quote": "Research shows Khan Academy Kids boosts pre-literacy skills."
    },
    {
      "ref": "D507",
      "area": "content",
      "claim": "A community post discusses the balance between parental safety concerns and children’s desire for fun, mentioning Khan Academy Kids as an example of a safe, educational app.",
      "stance": "neutral",
      "quote": "Parents want safety, kids want fun - how should schools balance both : r/preschool."
    }
  ]
}
